+function height(x,z){return 1.4*Math.sin(x*.027)*Math.cos(z*.023)+.65*Math.sin(z*.054+x*.016)+Math.max(0,1-Math.abs(x-95)/125)*Math.max(0,1-Math.abs(z+20)/170)*38+Math.max(0,1-Math.abs(x+145)/115)*Math.max(0,1-Math.abs(z-60)/190)*28;}
