+const size=520,div=150,positions=[],colors=[],indices=[];for(let j=0;j<=div;j++)for(let i=0;i<=div;i++){let x=(i/div-.5)*size,z=(j/div-.5)*size,y=height(x,z);positions.push(x,y,z);let c=new THREE.Color(y>28?0x777d70:y>13?0x6a7050:0x536343);let v=.92+Math.sin(x*.11+z*.13)*.045;c.multiplyScalar(v);colors.push(c.r,c.g,c.b);if(i<div&&j<div){let a=j*(div+1)+i,b=a+div+1;indices.push(a,b,a+1,b,b+1,a+1)}}const terrainGeo=new THREE.BufferGeometry();terrainGeo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));terrainGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));terrainGeo.setIndex(indices);terrainGeo.computeVertexNormals();const terrain=new THREE.Mesh(terrainGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));terrain.receiveShadow=true;scene.add(terrain);
