+for(let i=0;i<110;i++){let x=(rnd()-.5)*440,z=(rnd()-.5)*440;if(Math.abs(x-roadPoint((z+205)/410).x)<7)continue;let s=.6+rnd()*2.2,b=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),rockmat);b.position.set(x,height(x,z)+s*.45,z);b.rotation.set(rnd()*2,rnd()*3,rnd()*2);b.castShadow=true;b.receiveShadow=true;scene.add(b)}
+// Ramp features
+function ramp(x,z,rot=0){const m=new THREE.Mesh(new THREE.BoxGeometry(5,1.2,8),mat(0x8d6940));m.position.set(x,height(x,z)+.6,z);m.rotation.set(-.19,rot,0);m.castShadow=true;m.receiveShadow=true;scene.add(m);const stripe=new THREE.Mesh(new THREE.BoxGeometry(5.1,.14,.6),mat(0xd8ff3e));stripe.position.set(x,height(x,z)+1.2,z-3.1);stripe.rotation.y=rot;scene.add(stripe)}ramp(11,28,-.22);ramp(-24,-104,.16);ramp(27,142,.1);
+// Landmark flags + glowing navigation markers
+const gates=[];function makeGate(x,z,n){const y=height(x,z);let g=new THREE.Group();g.position.set(x,y,z);let poleMat=mat(0xe4e8d6,.5);for(let dx of [-5,5]){let p=new THREE.Mesh(new THREE.CylinderGeometry(.09,.09,4,8),poleMat);p.position.x=dx;p.position.y=2;g.add(p)}let bar=new THREE.Mesh(new THREE.BoxGeometry(10,.18,.2),mat(0xd8ff3e,.4));bar.position.y=3.8;g.add(bar);scene.add(g);gates.push(g)}for(let i=1;i<=5;i++){let p=roadPoint(i/6);makeGate(p.x,p.z,i)}
+// Bike geometry with articulated fork and wheels
+const bikeRoot=new THREE.Group();scene.add(bikeRoot);const bikeTilt=new THREE.Group();bikeRoot.add(bikeTilt);const bikePaint=new THREE.MeshStandardMaterial({color:0xe9432e,roughness:.42,metalness:.18});const dark=mat(0x171b18,.5,.28),rubber=mat(0x171916,1),metal=mat(0x9da7a0,.35,.72),seatmat=mat(0x242521,.75);
+function box(parent,geo,material,pos,rot){let m=new THREE.Mesh(geo,material);m.position.set(...pos);if(rot)m.rotation.set(...rot);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
+const wheelParts=[];for(let z of [-1.12,1.13]){let wh=new THREE.Group();wh.position.set(0,.64,z);bikeTilt.add(wh);let tire=new THREE.Mesh(new THREE.TorusGeometry(.53,.13,10,24),rubber);tire.rotation.y=Math.PI/2;tire.castShadow=true;wh.add(tire);let rim=new THREE.Mesh(new THREE.TorusGeometry(.35,.035,6,20),metal);rim.rotation.y=Math.PI/2;wh.add(rim);let hub=new THREE.Mesh(new THREE.CylinderGeometry(.09,.09,.19,12),metal);hub.rotation.z=Math.PI/2;wh.add(hub);for(let k=0;k<8;k++){let a=k*Math.PI/4;let spoke=new THREE.Mesh(new THREE.CylinderGeometry(.012,.012,.67,5),metal);spoke.rotation.z=a;spoke.rotation.x=Math.PI/2;wh.add(spoke)}wheelParts.push(wh)}
+box(bikeTilt,new THREE.BoxGeometry(.34,.38,.72),dark,[0,1.05,0]);box(bikeTilt,new THREE.BoxGeometry(.48,.16,.95),seatmat,[0,1.48,-.17],[.05,0,0]);box(bikeTilt,new THREE.BoxGeometry(.62,.54,.42),bikePaint,[0,1.39,.55],[.13,0,0]);box(bikeTilt,new THREE.BoxGeometry(.06,.68,.26),bikePaint,[0,1.14,1.12],[.15,0,0]);box(bikeTilt,new THREE.BoxGeometry(.06,.55,.3),bikePaint,[0,1.16,-1.05],[-.12,0,0]);box(bikeTilt,new THREE.CylinderGeometry(.1,.12,.43,12),metal,[0,1.08,-.35],[Math.PI/2,0,0]);
