const dustMat=new THREE.MeshBasicMaterial({color:0xbba77b,transparent:true,opacity:.35,depthWrite:false});const dust=[];for(let i=0;i<22;i++){let p=new THREE.Mesh(new THREE.SphereGeometry(.18+rnd()*.32,7,6),dustMat.clone());p.visible=false;scene.add(p);dust.push(p)}
let money=1250,owned=[true,false,false],bikeIndex=0,paintColors=[0xe9432e,0x3f9cff,0xe1d94b,0x67d178,0xe9e9df],paintIndex=0,helmetColors=[0xf0f0d7,0xf5a623,0x56c7bd,0xec536b],helmetIndex=0;
const bikeData=[{name:'ENDURO 250',desc:'ÁGIL · 250 CC · EQUILIBRADA',price:0,power:1,top:118},{name:'RALLY 450',desc:'POTENTE · 450 CC · RÁPIDA',price:2800,power:1.28,top:154},{name:'SERRA 650 R',desc:'TORQUE · 650 CC · BRUTA',price:6200,power:1.52,top:177}];
let mode='free',camMode=2,velocity=0,heading=0,vertical=0,air=false,groundY=0,wheelie=0,lean=0,elapsed=0,gateIndex=0,raceTime=0,rivals=[],raceDone=false,awardTimer=0,toastTimer=0;
const input={gas:false,brake:false,left:false,right:false};let audioCtx=null,osc=null,engineGain=null;
function setMoney(n){money=Math.max(0,n);$('#money').textContent='$ '+money.toLocaleString('en-US');$('#shopMoney').textContent='$ '+money.toLocaleString('en-US')}
function showToast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');toastTimer=2.2}
function openPanel(id){$('#'+id).classList.remove('hidden')};function closePanel(id){$('#'+id).classList.add('hidden')}
function buildShop(){ $('#bikes').innerHTML='';bikeData.forEach((b,i)=>{let d=document.createElement('div');d.className='bikecard'+(i===bikeIndex?' selected':'');d.innerHTML=`<div class="bikeicon">🏍</div><div><h3>${b.name}</h3><p>${b.desc}</p></div><button class="${owned[i]?'':'buy'}">${owned[i]?(i===bikeIndex?'EQUIPADA':'EQUIPAR'):'$ '+b.price.toLocaleString('en-US')}</button>`;d.querySelector('button').onclick=()=>{if(owned[i]){bikeIndex=i;showToast(b.name+' EQUIPADA')}else if(money>=b.price){setMoney(money-b.price);owned[i]=true;bikeIndex=i;showToast('MOTO DESBLOQUEADA!')}else showToast('CRÉDITOS INSUFICIENTES');buildShop();setBikeColor()};$('#bikes').append(d)});$('#bikeColors').innerHTML='';paintColors.forEach((c,i)=>{let b=document.createElement('button');b.className='swatch'+(i===paintIndex?' active':'');b.style.background='#'+c.toString(16).padStart(6,'0');b.onclick=()=>{paintIndex=i;setBikeColor();buildShop()};$('#bikeColors').append(b)});$('#helmetColors').innerHTML='';helmetColors.forEach((c,i)=>{let b=document.createElement('button');b.className='swatch'+(i===helmetIndex?' active':'');b.style.background='#'+c.toString(16).padStart(6,'0');b.onclick=()=>{helmetIndex=i;helmet.material.color.setHex(c);buildShop()};$('#helmetColors').append(b)})}
function setBikeColor(){bikePaint.color.setHex(paintColors[paintIndex])}buildShop();
function startAudio(){if(audioCtx)return;audioCtx=new (window.AudioContext||window.webkitAudioContext)();osc=audioCtx.createOscillator();let osc2=audioCtx.createOscillator();engineGain=audioCtx.createGain();let filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=400;osc.type='sawtooth';osc2.type='triangle';osc.frequency.value=48;osc2.frequency.value=24;let mix=audioCtx.createGain();mix.gain.value=.18;osc.connect(mix);osc2.connect(mix);mix.connect(filter);filter.connect(engineGain);engineGain.gain.value=.0001;engineGain.connect(audioCtx.destination);osc.start();osc2.start()}
function startGame(){closePanel('home');startAudio();if(audioCtx.state==='suspended')audioCtx.resume();bikeRoot.position.set(roadPoint(.06).x,height(roadPoint(.06).x,180)+.2,180);velocity=0;heading=0;mode='free';$('#objectiveTitle').textContent='EXPLORE SEM LIMITES';$('#objectiveSub').textContent='SERRA DO LOBO · BRASIL'}
function beginRace(type){closePanel('races');closePanel('home');startAudio();audioCtx?.resume();mode=type;raceTime=0;gateIndex=0;raceDone=false;$('#objectiveTitle').textContent=type==='sprint'?'TRILHA DO MIRANTE':'SALTO DO CÂNION';$('#objectiveSub').textContent='PORTÃO 1 / 5 · PASSE PELO MARCADOR';bikeRoot.position.set(roadPoint(.02).x,height(roadPoint(.02).x,197)+.25,197);velocity=0;heading=0;rivals.forEach(x=>scene.remove(x));rivals=[];for(let k=0;k<3;k++){let rival=new THREE.Mesh(new THREE.CapsuleGeometry(.44,.9,4,8),mat([0xed7549,0x418ec5,0xdacb69][k]));rival.position.set(k%2?7:-7,height(k%2?7:-7,197)+1,197+4+k*3);scene.add(rival);rivals.push(rival)}showToast('CORRIDA! PASSE PELOS PORTÕES')}
$('#playBtn').onclick=startGame;$('#homeRace').onclick=()=>{closePanel('home');openPanel('races')};$('#shopBtn').onclick=$('#garageBtn').onclick=()=>openPanel('garage');$('#raceBtn').onclick=()=>openPanel('races');$('#pauseBtn').onclick=()=>{$('#home').classList.contains('hidden')?openPanel('home'):closePanel('home')};$('#camBtn').onclick=()=>{camMode=camMode===2?1:2;showToast(camMode===1?'CÂMERA EM PRIMEIRA PESSOA':'CÂMERA EM TERCEIRA PESSOA')};$('#trickBtn').onclick=()=>{wheelie=1;showToast('WHEELIE!')};$$('[data-close]').forEach(b=>b.onclick=()=>closePanel(b.dataset.close));$$('.startRace').forEach(b=>b.onclick=()=>beginRace(b.dataset.race));
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['w','arrowup'].includes(k))input.gas=true;if(['s','arrowdown',' '].includes(k))input.brake=true;if(['a','arrowleft'].includes(k))input.left=true;if(['d','arrowright'].includes(k))input.right=true;if(k==='c')$('#camBtn').click();if(k==='shift')wheelie=1;if(k==='escape'){if(!$('#home').classList.contains('hidden'))closePanel('home');else openPanel('home')}if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault()});window.addEventListener('keyup',e=>{let k=e.key.toLowerCase();if(['w','arrowup'].includes(k))input.gas=false;if(['s','arrowdown',' '].includes(k))input.brake=false;if(['a','arrowleft'].includes(k))input.left=false;if(['d','arrowright'].includes(k))input.right=false});$$('[data-control]').forEach(b=>{let c=b.dataset.control;const down=e=>{e.preventDefault();input[c]=true;b.classList.add('active');b.setPointerCapture?.(e.pointerId)};const up=e=>{e.preventDefault();input[c]=false;b.classList.remove('active')};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up)});

